def insert(root, v):
    if root is None:
        return Node(v)
    if v < root.val:
        root.left = insert(root.left, v)
    elif v > root.val:
        root.right = insert(root.right, v)
    return root


def contains(root, v):
    node = root
    while node is not None:
        if v == node.val:
            return True
        node = node.left if v < node.val else node.right
    return False


def min_value(root):
    node = root
    while node.left is not None:
        node = node.left
    return node.val

