def validate_bst(root, lo=None, hi=None):
    if root is None:
        return True
    if lo is not None and root.val <= lo:
        return False
    if hi is not None and root.val >= hi:
        return False
    return (validate_bst(root.left, lo, root.val)
            and validate_bst(root.right, root.val, hi))

