def levels_between(root, lo, hi):
    out = []

    def walk(node):
        if node is None:
            return
        if node.val > lo:
            walk(node.left)
        if lo <= node.val <= hi:
            out.append(node.val)
        if node.val < hi:
            walk(node.right)

    walk(root)
    return out

