class _Seen(Node):
    seen = set()

    @property
    def val(self):
        _Seen.seen.add(id(self))
        return self._v

    @val.setter
    def val(self, v):
        self._v = v

def _copy(node):
    if node is None:
        return None
    return _Seen(node._v if isinstance(node, _Seen) else node.val, _copy(node.left), _copy(node.right))

def touched(root, lo, hi):
    """How many nodes levels_between reads."""
    t = _copy(root)
    _Seen.seen = set()
    levels_between(t, lo, hi)
    return len(_Seen.seen)
